flow.set("extrelay_rpc_response_topic", msg.rpcResponseTopic);

let operation = msg.operation || 'read';
const params = msg.rpcParams || {};

// If params has any writable field, it's a write
if (params.externalRelayFeatureEnabled !== undefined ||
    params.relayBitmapRaw !== undefined ||
    params.relays !== undefined) {
    operation = 'write';
}

msg.operation = operation;

if (operation === 'write') {
    return [null, msg];
} else {
    return [msg, null];
}

flow.set("extrelay_part_sn", null);
flow.set("extrelay_part_280", null);
flow.set("extrelay_part_296", null);

return msg;

msg.readGroup = "sn";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 3,
    quantity: 5
};
return msg;

msg.readGroup = "reg280";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 280,
    quantity: 1
};
return msg;

msg.readGroup = "reg296";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 296,
    quantity: 1
};
return msg;

let data = msg.payload;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (!Array.isArray(data)) {
    node.error("Invalid response for " + msg.readGroup);
    return null;
}

const group = msg.readGroup;

if (group === "sn") {
    flow.set("extrelay_part_sn", data);
} else if (group === "reg280") {
    flow.set("extrelay_part_280", data[0]);
    flow.set("extrelay_reg280_current", data[0]); // Store for bit manipulation
} else if (group === "reg296") {
    flow.set("extrelay_part_296", data[0]);
}

// Check if all parts received
const partSn = flow.get("extrelay_part_sn");
const part280 = flow.get("extrelay_part_280");
const part296 = flow.get("extrelay_part_296");

if (!partSn || part280 === null || part280 === undefined || 
    part296 === null || part296 === undefined) {
    return null;
}

msg.snData = partSn;
msg.reg280 = part280;
msg.reg296 = part296;
return msg;

const snData = msg.snData;
const reg280 = msg.reg280;
const reg296 = msg.reg296;

// Clear flow context
flow.set("extrelay_part_sn", null);
flow.set("extrelay_part_280", null);
flow.set("extrelay_part_296", null);

// Helper: Parse ASCII from packed register
function parseAsciiChar(val, high) {
    const byte = high ? ((val >> 8) & 0xFF) : (val & 0xFF);
    if (byte >= 0x20 && byte <= 0x7E) {
        return String.fromCharCode(byte);
    }
    return '';
}

// Helper: Parse Serial Number
function parseSerialNumber(regs) {
    let sn = '';
    for (let i = 0; i < 5; i++) {
        sn += parseAsciiChar(regs[i], true);
        sn += parseAsciiChar(regs[i], false);
    }
    return sn.trim();
}

// Helper: Get relay role based on index
function getRelayRole(index) {
    switch(index) {
        case 0: return "generator_start";
        case 1: return "alarm";
        case 2: return "dry_contact";
        default: return "spare";
    }
}

// Helper: Get relay description
function getRelayDescription(index) {
    switch(index) {
        case 0: return "Generator Start Signal";
        case 1: return "Alarm Output";
        case 2: return "Dry Contact Output";
        default: return "Spare Relay " + (index + 1);
    }
}

const serialNumber = parseSerialNumber(snData);

// Parse reg280 Bit13 for external relay enabled
const externalRelayFeatureEnabled = ((reg280 >> 13) & 0x01) === 1;

// Parse relay bitmap (reg296 Bit0-7)
const relayBitmapRaw = reg296 & 0xFF;

// Build relays array
const relays = [];
for (let i = 0; i < 8; i++) {
    const isActive = ((relayBitmapRaw >> i) & 0x01) === 1;
    relays.push({
        relayId: i + 1,
        logicalRole: getRelayRole(i),
        normallyOpen: isActive,
        description: getRelayDescription(i)
    });
}

const gatewayId = global.get("GATEWAY_ID") || env.get("GATEWAY_ID") || "EC100-GW-001";

const state = {
    kind: "ExternalRelayConfigState",
    timestampUtc: new Date().toISOString(),
    gatewayId: gatewayId,
    inverterSerialNumber: serialNumber,
    version: "1.0",

    externalRelayFeatureEnabled: externalRelayFeatureEnabled,
    relayBitmapRaw: relayBitmapRaw,
    relays: relays
};

// Check if this is after a write
const writeResult = flow.get("extrelay_write_result");
flow.set("extrelay_write_result", null);

const rpcResponseTopic = flow.get("extrelay_rpc_response_topic");
flow.set("extrelay_rpc_response_topic", null);

if (writeResult) {
    msg.payload = {
        success: true,
        message: `Successfully wrote ${writeResult.count} register(s)`,
        writes: writeResult.writes,
        state: state
    };
} else {
    msg.payload = state;
}

msg.rpcResponseTopic = rpcResponseTopic;

return msg;

if (!msg.rpcResponseTopic) {
    return null;
}

msg.topic = msg.rpcResponseTopic;
return msg;

const params = msg.rpcParams || {};
const writes = [];

// Get current reg280 value for bit manipulation
let reg280Current = flow.get("extrelay_reg280_current") || 0;

// 280 Bit13: externalRelayFeatureEnabled
if (params.externalRelayFeatureEnabled !== undefined) {
    if (params.externalRelayFeatureEnabled) {
        reg280Current |= (1 << 13);  // Set bit 13
    } else {
        reg280Current &= ~(1 << 13); // Clear bit 13
    }
    writes.push({ register: 280, value: reg280Current, name: "Ext Relay Enable (Bit13)" });
}

// 296: relayBitmapRaw
if (params.relayBitmapRaw !== undefined) {
    const val = params.relayBitmapRaw & 0xFF;
    writes.push({ register: 296, value: val, name: "Relay Bitmap" });
}

// If relays array provided, build bitmap from it
if (params.relays && Array.isArray(params.relays)) {
    let bitmap = 0;
    for (const relay of params.relays) {
        if (relay.relayId >= 1 && relay.relayId <= 8 && relay.normallyOpen) {
            bitmap |= (1 << (relay.relayId - 1));
        }
    }
    // Check if we already have a write for 296, update it
    const existing = writes.find(w => w.register === 296);
    if (existing) {
        existing.value = bitmap;
    } else {
        writes.push({ register: 296, value: bitmap, name: "Relay Bitmap" });
    }
}

if (writes.length === 0) {
    node.warn("No valid parameters to write");
    // Do read anyway
    return [null, msg];
}

global.set("extrelay_write_queue", writes);
global.set("extrelay_write_index", 0);
global.set("extrelay_write_results", []);

node.status({ fill: "blue", shape: "dot", text: writes.length + " writes queued" });

return [msg, null];

// Need to read reg280 first to preserve other bits
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 280,
    quantity: 1
};
return msg;

let data = msg.payload;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

const reg280Current = Array.isArray(data) ? data[0] : 0;
flow.set("extrelay_reg280_current", reg280Current);

// Now update the write queue with correct bit manipulation
const writes = global.get("extrelay_write_queue") || [];
const params = msg.rpcParams || {};

for (let i = 0; i < writes.length; i++) {
    if (writes[i].register === 280) {
        let newVal = reg280Current;
        if (params.externalRelayFeatureEnabled !== undefined) {
            if (params.externalRelayFeatureEnabled) {
                newVal |= (1 << 13);
            } else {
                newVal &= ~(1 << 13);
            }
        }
        writes[i].value = newVal;
    }
}

global.set("extrelay_write_queue", writes);

return msg;

const writes = global.get("extrelay_write_queue") || [];
const index = global.get("extrelay_write_index") || 0;

if (index >= writes.length) {
    return null;
}

const current = writes[index];

msg.payload = {
    fc: 16,
    unitid: 1,
    address: current.register,
    quantity: 1,
    value: [current.value]
};
msg.currentWrite = current;

node.status({ fill: "blue", shape: "dot", text: `[${index+1}/${writes.length}] ${current.name}` });

return msg;

const writes = global.get("extrelay_write_queue") || [];
let index = global.get("extrelay_write_index") || 0;
const results = global.get("extrelay_write_results") || [];

const current = msg.currentWrite;
if (current) {
    results.push({
        register: current.register,
        name: current.name,
        value: current.value,
        success: true
    });
    global.set("extrelay_write_results", results);
}

index++;
global.set("extrelay_write_index", index);

node.status({ fill: "green", shape: "dot", text: `${current.name} OK` });

if (index < writes.length) {
    return [msg, null];
}

// All writes done
flow.set("extrelay_write_result", {
    count: results.length,
    writes: results
});

global.set("extrelay_write_queue", null);
global.set("extrelay_write_index", null);
global.set("extrelay_write_results", null);

return [null, msg];
